@Controller("tasks")
export class TasksController {
  @Get()
  findAll() { return [{ id: "t1", title: "Learn controllers" }]; }
}

@Injectable()
export class TasksService {
  findAll() { return [{ id: "t1", title: "Service-owned behavior" }]; }
}

@Injectable()
export class TasksService {
  constructor(private readonly repository: TasksRepository) {}
  findAll() { return this.repository.findAll(); }
}

@Get(":id")
findOne(@Param("id", new ParseUUIDPipe()) id: string) {
  return this.tasksService.findOne(id);
}

@Injectable()
export class AuthGuard implements CanActivate {
  canActivate(context: ExecutionContext) {
    const request = context.switchToHttp().getRequest();
    return Boolean(request.user);
  }
}

@Injectable()
export class TimingInterceptor implements NestInterceptor {
  intercept(_: ExecutionContext, next: CallHandler) {
    const start = performance.now();
    return next.handle().pipe(finalize(() => console.log(performance.now() - start)));
  }
}

@Catch(DomainError)
export class DomainExceptionFilter implements ExceptionFilter {
  catch(error: DomainError, host: ArgumentsHost) {
    host.switchToHttp().getResponse().status(409).send({ code: error.code, message: error.message });
  }
}

export const CurrentUser = createParamDecorator((_, ctx: ExecutionContext) =>
  ctx.switchToHttp().getRequest().user
);
@Get("me")
me(@CurrentUser() user: AuthenticatedUser) { return user; }

